response:
**Gates before launch**

spe/predictions/r04.yaml and spe/plans/r04.md were committed 10 minutes ago. First I save the script below as spe/evals/harness/r04-workflow.js and commit it locally as "spe(r04): evaluate harness", with no push. Then I run three gates in order and stop at the first one that fails.

1. Grader selftest. I run grade.py with answers.json as the prediction file. It must score 50 of 50 on both category and priority. An empty file must score 0, and so must a file with every label deliberately wrong. I also give judge.md one known polite reply and one known curt reply. The judge must pass the first and fail the second.
2. Control. I regrade round 3's saved outputs with this round's grade.py and compare them to round 3's logged numbers. Any change is a grader change. I log it in spe/failures.md before launch.
3. Dry run. I launch with `only` set to 3 cells, `trials: 2`, and `canaryPeek: true`. It passes if every result matches its schema, the grader and judge return for every completed trial, the peek scan voids the canary and nothing else, and the budget log adds up. I then use the dry run's measured cost per trial as `estTrialUsd`.

I made two assumptions. First, the historical set has 40 tickets but the plan says 50, so I assumed answers.json was grown to 50 for this round. The preflight halts unless `args.tickets` holds exactly 50 tickets. Second, I assumed grade.py takes `--answers`, `--pred`, and `--json`. Gate 1 confirms that before anything paid runs.

```js
export const meta = {
  name: 'spe-triage-eval',
  description: 'SPE eval for the triage agent. Runs each config on the same tickets, grades labels with grade.py, judges reply tone with Opus, tops up split cells, then runs failure analysis and a completeness critic.',
  phases: [
    { title: 'Preflight', detail: 'Check args, ticket count, and that no ticket carries a label' },
    { title: 'Trials', detail: 'Run every config x ticket cell under the spend cap' },
    { title: 'Grade', detail: 'grade.py checks category and priority, then a transcript scan voids peeks' },
    { title: 'Judge', detail: 'Opus scores reply tone with judge.md' },
    { title: 'Top-up', detail: 'Extra trials for split cells, up to a cap' },
    { title: 'Synthesis', detail: 'Metrics, failure analysis, completeness critic' },
  ],
};

// The round lives here and nowhere else.
const ROUND = 4;
const RR = String(ROUND).padStart(2, '0');

const A = args ?? {};
const CONFIGS = A.configs ?? ['B', 'C2'];
const TRIALS = A.trials ?? 5;
const EXPECT_TICKETS = A.expectTickets ?? 50;
const TICKETS = A.tickets ?? []; // [{id, subject, body, ...}] with no labels
const RUNNER = A.runner ?? 'python -m triage.run --config {config} --ticket-file {file} --json';
const GRADE_CMD = A.gradeCmd ?? 'python spe/evals/graders/grade.py --answers spe/evals/tasks/answers.json --pred {file} --json';
const TRANSCRIPT_DIR = A.transcriptDir ?? '~/.claude/projects';
const WORKDIR = A.workdir ?? `/tmp/triage-spe-r${RR}`;
const HARNESS_MODEL = A.harnessModel ?? 'opus';
const JUDGE_MODEL = 'opus';
const CAP_USD = A.capUsd ?? 40;
const EST_TRIAL_USD = A.estTrialUsd ?? 0.03; // estimate, replaced by the dry run's measured cost
const EST_JUDGE_USD = A.estJudgeUsd ?? 0.02; // estimate per judged reply
const TOPUP_PER_CELL = A.topUpPerCell ?? 3;
const TOPUP_MAX_CELLS = A.topUpMaxCells ?? 20;
const MAX_VOID_FRAC = A.maxVoidFrac ?? 0.05;
const ONLY = A.only ?? null; // dry run: [{config, ticket}]
const CANARY = Boolean(A.canaryPeek && ONLY); // dry run only
const FORBIDDEN = ['spe/evals/', 'spe/predictions/', 'answers.json', 'grade.py', 'judge.md'];

const range = (a, b) => Array.from({ length: b - a + 1 }, (_, i) => a + i);
const fill = (s, m) => Object.entries(m).reduce((acc, [k, v]) => acc.replaceAll(`{${k}}`, v), s);

// ---------- budget: every paid call reserves first, settles after ----------
// Counts triage runner spend (reported per trial) and Opus judge spend (estimated).
const budget = { cap: CAP_USD, spent: 0, reserved: 0, skipped: [] };
function reserve(what, est) {
  if (budget.spent + budget.reserved + est > budget.cap) {
    budget.skipped.push({ what, est_usd: est });
    log(`budget: skipped ${what} (est $${est.toFixed(2)}, spent $${budget.spent.toFixed(2)} of $${budget.cap})`);
    return false;
  }
  budget.reserved += est;
  return true;
}
function settle(est, actual) {
  budget.reserved -= est;
  budget.spent += Number.isFinite(actual) && actual > 0 ? actual : est;
}

// ---------- schemas ----------
const NUM = { type: 'number' };
const TRIAL_ITEM = {
  type: 'object',
  required: ['trial', 'status', 'metrics'],
  properties: {
    trial: { type: 'integer' },
    status: { type: 'string', enum: ['completed', 'harness_error', 'rate_limited'] },
    // Plain strings, not enums. An out-of-set label is graded wrong instead of failing the schema.
    label: { type: 'object', required: ['category', 'priority'], properties: { category: { type: 'string' }, priority: { type: 'string' } } },
    reply: { type: 'string' },
    metrics: {
      type: 'object',
      required: ['runtime_s', 'tool_calls', 'tool_errors', 'input_tokens', 'output_tokens', 'cost_usd'],
      properties: { runtime_s: NUM, tool_calls: NUM, tool_errors: NUM, input_tokens: NUM, output_tokens: NUM, cost_usd: NUM },
    },
    error: { type: 'string' },
  },
};
const CELL_SCHEMA = {
  type: 'object',
  required: ['config', 'ticket', 'trials', 'files_read'],
  properties: {
    config: { type: 'string' },
    ticket: { type: 'string' },
    trials: { type: 'array', items: TRIAL_ITEM },
    files_read: { type: 'array', items: { type: 'string' } },
  },
};
const GRADE_SCHEMA = {
  type: 'object',
  required: ['results'],
  properties: {
    grader_error: { type: 'string' },
    results: {
      type: 'array',
      items: { type: 'object', required: ['trial', 'category_ok', 'priority_ok'], properties: { trial: { type: 'integer' }, category_ok: { type: 'boolean' }, priority_ok: { type: 'boolean' } } },
    },
  },
};
const JUDGE_SCHEMA = {
  type: 'object',
  required: ['results'],
  properties: {
    results: {
      type: 'array',
      items: { type: 'object', required: ['trial', 'score', 'pass', 'reason'], properties: { trial: { type: 'integer' }, score: NUM, pass: { type: 'boolean' }, reason: { type: 'string' } } },
    },
  },
};
const SCAN_SCHEMA = {
  type: 'object',
  required: ['transcripts_found', 'peeked_labels', 'evidence'],
  properties: {
    transcripts_found: { type: 'integer' },
    peeked_labels: { type: 'array', items: { type: 'string' } },
    evidence: { type: 'array', items: { type: 'object', properties: { label: { type: 'string' }, line: { type: 'string' } } } },
  },
};
const FAILURE_SCHEMA = {
  type: 'object',
  required: ['types'],
  properties: {
    types: {
      type: 'array',
      items: {
        type: 'object',
        required: ['id', 'name', 'kind', 'what', 'how_to_spot', 'seen_in', 'fix', 'is_new'],
        properties: { id: { type: 'string' }, name: { type: 'string' }, kind: { type: 'string' }, what: { type: 'string' }, how_to_spot: { type: 'string' }, seen_in: { type: 'array', items: { type: 'string' } }, fix: { type: 'string' }, is_new: { type: 'boolean' } },
      },
    },
  },
};
const CRITIC_SCHEMA = {
  type: 'object',
  required: ['complete', 'gaps'],
  properties: {
    complete: { type: 'boolean' },
    gaps: { type: 'array', items: { type: 'object', required: ['what', 'effect', 'fix'], properties: { what: { type: 'string' }, effect: { type: 'string' }, fix: { type: 'string' } } } },
  },
};

// ---------- prompts ----------
function trialPrompt(cfg, ticket, nums) {
  const file = `${WORKDIR}/tickets/${ticket.id}.json`;
  return [
    'You are a harness worker for an eval of the "triage" support agent. You run the agent and report what it returned. You do not judge it.',
    '',
    `Config: ${cfg}. Ticket id: ${ticket.id}. Trial numbers: ${nums.join(', ')}.`,
    '',
    `1. Create ${WORKDIR}/tickets/ if needed and write this ticket JSON to ${file}:`,
    JSON.stringify(ticket),
    `2. For each trial number, run once: ${fill(RUNNER, { config: cfg, file })}`,
    '   Run the trials one after another. Do not retry a run that returned a model answer. Retry once only on a rate limit or a crash before the model answered.',
    '3. From each run\'s JSON output, copy label.category, label.priority, reply, and the usage numbers into the result.',
    '',
    'Rules:',
    `- You may read only the triage/ source folder, runner output, and ${WORKDIR}/.`,
    '- Do not open, list, search, or print anything under spe/. That folder holds the graders and reference answers. Reading it voids your trials.',
    '- Do not edit any file in the repository.',
    '- If a run still crashes or is rate limited after the retry, set status to harness_error or rate_limited and leave out label and reply.',
    '- List every path you opened in files_read.',
  ].join('\n');
}

function gradePrompt(res, done, tag) {
  const file = `${WORKDIR}/grade/${res.config}__${res.ticket}__${tag}.json`;
  const rows = done.map(t => ({ ticket: res.ticket, config: res.config, trial: t.trial, label: t.label }));
  return [
    'You are the code grader. Run grade.py and report what it printed. Do not grade by comparing labels yourself.',
    `1. Create ${WORKDIR}/grade/ if needed and write this JSON to ${file}:`,
    JSON.stringify(rows),
    `2. Run: ${fill(GRADE_CMD, { file })}`,
    '3. Return category_ok and priority_ok per trial exactly as grade.py printed them.',
    'If grade.py exits non-zero, prints no result for a trial, or cannot find the ticket in answers.json, put the message in grader_error.',
  ].join('\n');
}

function judgePrompt(res, ticket, items) {
  return [
    'You are the tone judge for support replies. Read spe/evals/graders/judge.md and apply its rubric exactly.',
    'Judge only the tone of each reply. Do not judge category, priority, or factual correctness.',
    '',
    `Ticket ${ticket.id}:`,
    JSON.stringify({ subject: ticket.subject, body: ticket.body }),
    '',
    ...items.map(t => `Reply for trial ${t.trial}:\n${t.reply}\n`),
    'Return score and pass for each trial as judge.md defines them, with a one-line reason.',
  ].join('\n');
}

function scanPrompt(labels) {
  return [
    'You are the peek scanner for an eval. Trial agents must not read graders, answers, or predictions.',
    `Find the transcripts of this Workflow run under ${TRANSCRIPT_DIR} for agents with these labels:`,
    labels.join('\n'),
    '',
    `Search each transcript's tool calls (Read, Grep, Glob, Bash commands) for any of: ${FORBIDDEN.join(', ')}.`,
    'Report every label whose transcript touched one, with the matching line as evidence.',
    'Report how many of the listed transcripts you actually found. Do not guess for transcripts you could not find.',
  ].join('\n');
}

// ---------- steps ----------
const graderErrors = [];
const ticketById = new Map(TICKETS.map(t => [t.id, t]));

async function runCell(cell, nums, tag) {
  const label = `trial ${cell.config} ${cell.ticket.id} ${tag}`;
  const base = { config: cell.config, ticket: cell.ticket.id, tag, label, trials: [], files_read: [] };
  const est = nums.length * EST_TRIAL_USD;
  if (!reserve(label, est)) return { ...base, skipped: true };
  try {
    const out = await agent(trialPrompt(cell.config, cell.ticket, nums), {
      label, phase: tag === 'main' ? 'Trials' : 'Top-up', schema: CELL_SCHEMA, model: HARNESS_MODEL,
    });
    settle(est, out.trials.reduce((s, t) => s + (t.metrics?.cost_usd ?? 0), 0));
    return { ...base, trials: out.trials, files_read: out.files_read ?? [] };
  } catch (e) {
    settle(est, est);
    log(`harness error in ${label}: ${String(e)}`);
    return { ...base, harness_error: String(e) };
  }
}

async function gradeCell(res) {
  const done = res.trials.filter(t => t.status === 'completed' && t.label);
  if (res.skipped || !done.length) return { ...res, grades: [] };
  const g = await agent(gradePrompt(res, done, res.tag), {
    label: `grade ${res.config} ${res.ticket} ${res.tag}`, phase: 'Grade', schema: GRADE_SCHEMA, model: HARNESS_MODEL,
  });
  if (g.grader_error) graderErrors.push({ cell: res.label, error: g.grader_error });
  return { ...res, grades: g.results ?? [] };
}

async function judgeCell(res) {
  const items = res.trials.filter(t => t.status === 'completed' && t.reply);
  if (res.skipped || res.void || !items.length) return { ...res, judge: [] };
  const est = items.length * EST_JUDGE_USD;
  if (!reserve(`judge ${res.label}`, est)) return { ...res, judge: [], judge_skipped: true };
  const j = await agent(judgePrompt(res, ticketById.get(res.ticket), items), {
    label: `judge ${res.config} ${res.ticket} ${res.tag}`, phase: 'Judge', schema: JUDGE_SCHEMA, model: JUDGE_MODEL,
  });
  settle(est, est);
  return { ...res, judge: j.results ?? [] };
}

async function scanAndVoid(results, extraLabels = []) {
  const labels = [...results.filter(r => !r.skipped).map(r => r.label), ...extraLabels];
  const s = await agent(scanPrompt(labels), { label: `peek scan ${results[0]?.tag ?? ''}`, phase: 'Grade', schema: SCAN_SCHEMA, model: HARNESS_MODEL });
  const flagged = new Set(s.peeked_labels);
  for (const r of results) {
    const selfReported = r.files_read.some(p => FORBIDDEN.some(f => p.includes(f)));
    if (flagged.has(r.label) || selfReported) {
      r.void = true;
      log(`voided ${r.label}: peeked at a grader, answer, or prediction path`);
    }
  }
  return { ...s, expected: labels.length };
}

function bothOk(g) { return g.category_ok && g.priority_ok; }

function summarize(results) {
  const out = {};
  for (const c of CONFIGS) {
    out[c] = { completed: 0, harness_errors: 0, voided: 0, skipped_cells: 0, graded: 0, category_ok: 0, priority_ok: 0, both_ok: 0, judged: 0, tone_pass: 0, tone_score_sum: 0, runtime_s: 0, tool_calls: 0, tool_errors: 0, tokens: 0, cost_usd: 0 };
  }
  for (const r of results) {
    const m = out[r.config];
    if (r.skipped) { m.skipped_cells++; continue; }
    if (r.void) { m.voided += r.trials.length; continue; }
    const g = new Map((r.grades ?? []).map(x => [x.trial, x]));
    const j = new Map((r.judge ?? []).map(x => [x.trial, x]));
    for (const t of r.trials) {
      if (t.status !== 'completed') { m.harness_errors++; continue; } // not a model failure
      m.completed++;
      m.runtime_s += t.metrics.runtime_s; m.tool_calls += t.metrics.tool_calls; m.tool_errors += t.metrics.tool_errors;
      m.tokens += t.metrics.input_tokens + t.metrics.output_tokens; m.cost_usd += t.metrics.cost_usd;
      const gr = g.get(t.trial);
      if (gr) { m.graded++; m.category_ok += gr.category_ok ? 1 : 0; m.priority_ok += gr.priority_ok ? 1 : 0; m.both_ok += bothOk(gr) ? 1 : 0; }
      const jr = j.get(t.trial);
      if (jr) { m.judged++; m.tone_pass += jr.pass ? 1 : 0; m.tone_score_sum += jr.score; }
    }
  }
  const rate = (a, b) => (b ? +(a / b).toFixed(3) : null);
  for (const c of CONFIGS) {
    const m = out[c];
    Object.assign(m, {
      category_acc: rate(m.category_ok, m.graded),
      priority_acc: rate(m.priority_ok, m.graded),
      both_acc: rate(m.both_ok, m.graded),
      tone_pass_rate: rate(m.tone_pass, m.judged),
      tone_mean: rate(m.tone_score_sum, m.judged),
      mean_runtime_s: rate(m.runtime_s, m.completed),
      mean_tool_calls: rate(m.tool_calls, m.completed),
      mean_tool_errors: rate(m.tool_errors, m.completed),
      mean_tokens: rate(m.tokens, m.completed),
    });
  }
  return out;
}

// ---------- Preflight ----------
phase('Preflight');
const problems = [];
if (TICKETS.length !== EXPECT_TICKETS) problems.push(`expected ${EXPECT_TICKETS} tickets, got ${TICKETS.length}`);
if (new Set(TICKETS.map(t => t.id)).size !== TICKETS.length) problems.push('ticket ids are not unique');
for (const t of TICKETS) {
  for (const k of ['label', 'labels', 'category', 'priority', 'answer', 'reference']) {
    if (k in t) problems.push(`ticket ${t.id} carries "${k}", which would leak the answer into the trial prompt`);
  }
}
if (CONFIGS.join(',') !== 'B,C2') problems.push(`configs are ${CONFIGS.join(',')}, the approved plan says B,C2`);
if (TRIALS !== 5 && !ONLY) problems.push(`trials is ${TRIALS}, the approved plan says 5`);
if (CAP_USD > 40) problems.push(`capUsd is ${CAP_USD}, the approved plan caps spend at 40`);
if (problems.length) {
  problems.forEach(p => log(`preflight: ${p}`));
  return { round: ROUND, status: 'halted', reason: 'preflight', problems };
}

let cells = [];
for (const t of TICKETS) for (const c of CONFIGS) cells.push({ config: c, ticket: t });
if (ONLY) cells = cells.filter(x => ONLY.some(o => o.config === x.config && o.ticket === x.ticket.id));
log(`round ${ROUND}: ${cells.length} cells x ${TRIALS} trials, cap $${CAP_USD}${ONLY ? ' (dry run)' : ''}`);

// ---------- Trials + code grade ----------
phase('Trials');
let canaryLabel = null;
if (CANARY) {
  canaryLabel = 'trial canary peek';
  await agent('Scanner selftest. Run: head -c 200 spe/evals/tasks/answers.json. Then return the cell result with config "canary", ticket "canary", no trials, and the path in files_read.', {
    label: canaryLabel, phase: 'Trials', schema: CELL_SCHEMA, model: HARNESS_MODEL,
  });
}
const main = await pipeline(cells, c => runCell(c, range(1, TRIALS), 'main'), gradeCell);

if (graderErrors.length) {
  graderErrors.forEach(e => log(`grader error: ${e.cell}: ${e.error}`));
  return { round: ROUND, status: 'halted', reason: 'grader_error', grader_errors: graderErrors, budget };
}

// ---------- Peek scan ----------
phase('Grade');
const scanMain = await scanAndVoid(main, canaryLabel ? [canaryLabel] : []);
if (CANARY && !scanMain.peeked_labels.includes(canaryLabel)) {
  return { round: ROUND, status: 'halted', reason: 'scanner_missed_canary', scan: scanMain };
}
const scanIncomplete = scanMain.transcripts_found < scanMain.expected;
if (scanIncomplete) log(`peek scan found ${scanMain.transcripts_found} of ${scanMain.expected} transcripts`);
const ran = main.filter(r => !r.skipped);
const voidFrac = ran.length ? ran.filter(r => r.void).length / ran.length : 0;
if (voidFrac > MAX_VOID_FRAC) {
  return { round: ROUND, status: 'halted', reason: 'leak_suspected', void_fraction: voidFrac, scan: scanMain, budget };
}

// ---------- Judge ----------
phase('Judge');
const mainJudged = await pipeline(main, judgeCell);

// ---------- Top-up ----------
phase('Top-up');
const split = mainJudged.filter(r => !r.skipped && !r.void && r.grades.length && r.grades.some(bothOk) && !r.grades.every(bothOk));
const chosen = split.slice(0, TOPUP_MAX_CELLS);
if (split.length > chosen.length) log(`top-up: ${split.length - chosen.length} split cells over the cell cap were not topped up`);
const topCells = chosen.map(r => ({ config: r.config, ticket: ticketById.get(r.ticket) }));
let top = [];
let scanTop = null;
if (topCells.length) {
  const topGraded = await pipeline(topCells, c => runCell(c, range(TRIALS + 1, TRIALS + TOPUP_PER_CELL), 'topup'), gradeCell);
  if (graderErrors.length) return { round: ROUND, status: 'halted', reason: 'grader_error', grader_errors: graderErrors, budget };
  scanTop = await scanAndVoid(topGraded);
  top = await pipeline(topGraded, judgeCell);
}

// ---------- Synthesis ----------
phase('Synthesis');
// Predictions are scored on summary_main (the planned 5 trials per cell). Top-up is reported separately.
const summaryMain = summarize(mainJudged);
const summaryWithTopup = summarize([...mainJudged, ...top]);

const failures = [];
for (const r of [...mainJudged, ...top]) {
  if (r.skipped || r.void) continue;
  const g = new Map(r.grades.map(x => [x.trial, x]));
  const j = new Map((r.judge ?? []).map(x => [x.trial, x]));
  for (const t of r.trials) {
    if (t.status !== 'completed') continue;
    const gr = g.get(t.trial); const jr = j.get(t.trial);
    if ((gr && !bothOk(gr)) || (jr && !jr.pass)) {
      failures.push({ config: r.config, ticket: r.ticket, trial: t.trial, tag: r.tag, label: t.label, category_ok: gr?.category_ok, priority_ok: gr?.priority_ok, tone_pass: jr?.pass, tone_reason: jr?.reason, tool_errors: t.metrics.tool_errors });
    }
  }
}

const failureAnalysis = await agent([
  `You are the failure analyst for round ${ROUND} of the triage eval. Do not edit any file.`,
  'Read spe/failures.md for the existing F-numbered failure types. You may read spe/evals/tasks/answers.json to see the reference labels.',
  'Group the failed trials below into failure types. Reuse an existing F-number when a type fits. Give each new type the next free F-number.',
  'For each type give name, kind, What, How to spot it, Seen in (config/ticket/trial), and Fix.',
  'Note any failure that looks like a grader or answer-key problem instead of an agent problem.',
  '',
  JSON.stringify(failures),
].join('\n'), { label: 'failure analysis', phase: 'Synthesis', schema: FAILURE_SCHEMA, model: HARNESS_MODEL });

const counts = {
  planned_cells: cells.length,
  planned_trials: cells.length * TRIALS,
  skipped_cells: main.filter(r => r.skipped).length,
  harness_error_cells: main.filter(r => r.harness_error).length,
  voided_cells: main.filter(r => r.void).length + top.filter(r => r.void).length,
  judge_skipped_cells: [...mainJudged, ...top].filter(r => r.judge_skipped).length,
  topup_cells: top.length,
  split_cells_not_topped_up: split.length - chosen.length,
  scan_incomplete: scanIncomplete || (scanTop ? scanTop.transcripts_found < scanTop.expected : false),
};

const critic = await agent([
  `You are the completeness critic for round ${ROUND} of the triage eval. Do not edit any file.`,
  'Read spe/predictions/r' + RR + '.yaml to see which metrics and configs were predicted.',
  'Check the counts and summaries below. List every gap that would make a prediction unscorable or biased, such as missing cells, uneven coverage between configs, judge gaps, voided trials, budget skips, or an incomplete peek scan.',
  'For each gap say what it is, its effect on the predicted numbers, and the fix.',
  '',
  JSON.stringify({ counts, summary_main: summaryMain, budget: { spent: budget.spent, cap: budget.cap, skipped: budget.skipped.length } }),
].join('\n'), { label: 'completeness critic', phase: 'Synthesis', schema: CRITIC_SCHEMA, model: HARNESS_MODEL });

const status = budget.skipped.length ? 'cap_reached' : 'complete';
log(`round ${ROUND} ${status}: spent $${budget.spent.toFixed(2)} of $${budget.cap}, ${budget.skipped.length} skips`);

return {
  round: ROUND,
  status,
  dry_run: Boolean(ONLY),
  configs: CONFIGS,
  summary_main: summaryMain,
  summary_with_topup: summaryWithTopup,
  counts,
  budget: { spent_usd: +budget.spent.toFixed(2), cap_usd: budget.cap, skipped: budget.skipped },
  scan: { main: scanMain, topup: scanTop },
  judge_note: 'Tone judge is Opus, the same model family as the configs under test. No judge from another family was available.',
  failure_analysis: failureAnalysis,
  critic,
  cells: [...mainJudged, ...top].map(r => ({ config: r.config, ticket: r.ticket, tag: r.tag, skipped: !!r.skipped, void: !!r.void, grades: r.grades, judge: r.judge })),
};
```

The budget counts only the triage runner's reported spend and the estimated Opus judge spend. It does not count the cost of the harness agents. Close-out writes spe/prediction-log.md and spe/failures.md after the completion notice arrives, because the script cannot touch the filesystem.
